/* APEX//RIP — mobile-first glossy dark UI */
*,*::before,*::after{box-sizing:border-box}
:root{
  --bg:#05060b;
  --bg-2:#090c15;
  --ink:#f2f5ff;
  --muted:#8a94a9;
  --dim:#5c6577;
  --line:rgba(255,255,255,.085);
  --line-2:rgba(255,255,255,.15);
  --glass:rgba(13,17,27,.72);
  --glass-2:rgba(16,21,33,.9);
  --cyan:#4fe3ff;
  --pink:#ff3d86;
  --gold:#ffc247;
  --green:#43ffa3;
  --violet:#9d6bff;
  --danger:#ff5a63;
  --tab-h:calc(66px + env(safe-area-inset-bottom, 0px));
  --radius:22px;
  --app-w:520px;
  --font:"SF Pro Display",-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
}
html,body{
  height:100%;margin:0;padding:0;overflow:hidden;overscroll-behavior:none;
  background:#03040a;color:var(--ink);font-family:var(--font);
  -webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility;
}
body{position:fixed;inset:0;width:100%;height:100dvh;min-height:100dvh;touch-action:none}
button,input{font:inherit;color:inherit}
button{border:0;background:none;cursor:pointer;-webkit-tap-highlight-color:transparent;touch-action:manipulation}
button:focus-visible{outline:2px solid var(--cyan);outline-offset:2px}
h1,h2,h3,h4,p{margin:0}
img,svg{display:block}
#app{position:fixed;inset:0;height:100dvh;width:100%;overflow:hidden;isolation:isolate;background:
  radial-gradient(120% 60% at 50% -10%,#111a2e 0%,#070a12 42%,#03040a 100%)}
#gl{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none;z-index:0}
.scene-tint{position:absolute;inset:0;z-index:1;pointer-events:none;background:
  linear-gradient(180deg,rgba(3,4,10,.72) 0%,rgba(3,4,10,.1) 22%,transparent 46%,rgba(3,4,10,.2) 66%,rgba(3,4,10,.82) 100%)}
.vignette{position:absolute;inset:0;z-index:1;pointer-events:none;background:
  radial-gradient(105% 80% at 50% 42%,transparent 48%,rgba(0,0,0,.42) 100%)}

/* boot / fatal */
.boot{position:fixed;inset:0;z-index:90;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;background:radial-gradient(80% 60% at 50% 40%,#0a1020,#03040a 70%);transition:opacity .5s ease,visibility .5s}
.boot.done{opacity:0;visibility:hidden;pointer-events:none}
.boot-mark{display:flex;gap:5px;height:28px;align-items:flex-end;margin-bottom:4px}
.boot-mark span{width:6px;border-radius:2px;background:linear-gradient(180deg,var(--cyan),#1377ff);animation:bootbars .9s ease-in-out infinite alternate}
.boot-mark span:nth-child(1){height:14px;animation-delay:0s}
.boot-mark span:nth-child(2){height:28px;animation-delay:.12s;background:linear-gradient(180deg,var(--pink),#8b1dff)}
.boot-mark span:nth-child(3){height:20px;animation-delay:.24s}
@keyframes bootbars{to{transform:scaleY(.45);opacity:.5}}
.boot-title{font-size:30px;font-weight:900;letter-spacing:.16em;font-style:italic;text-shadow:0 0 30px rgba(79,227,255,.35)}
.boot-title span{color:var(--pink)}
.boot-sub{color:var(--muted);font-size:11px;letter-spacing:.22em;text-transform:uppercase}
.fatal{position:fixed;inset:0;z-index:100;display:grid;place-items:center;padding:24px;background:#03040a}
.fatal[hidden]{display:none}
.fatal-card{width:min(360px,100%);padding:24px;border-radius:22px;background:linear-gradient(160deg,#131a28,#0a0d15);border:1px solid var(--line-2);box-shadow:0 30px 80px #000}
.fatal-kicker{color:var(--danger);font-size:10px;letter-spacing:.24em;font-weight:800;margin-bottom:8px}
.fatal-card h2{font-size:24px;letter-spacing:-.02em;margin-bottom:8px}
.fatal-card p{color:var(--muted);font-size:13px;line-height:1.5;margin-bottom:18px}
.fatal-actions{display:flex;gap:10px}

/* HUD */
.hud{
  position:fixed;z-index:30;top:0;left:50%;transform:translateX(-50%);
  width:100%;max-width:var(--app-w);
  padding:calc(10px + env(safe-area-inset-top,0px)) 14px 8px;
  display:flex;align-items:center;justify-content:space-between;gap:10px;
  background:linear-gradient(180deg,rgba(3,4,10,.86),rgba(3,4,10,0));
  pointer-events:none;
}
.hud>*{pointer-events:auto}
.brand{display:flex;align-items:center;gap:8px;min-width:0}
.brand-mark{width:30px;height:30px;border-radius:9px;display:grid;place-items:center;background:linear-gradient(145deg,#1a2940,#0a0e18);border:1px solid rgba(79,227,255,.35);box-shadow:inset 0 1px 0 rgba(255,255,255,.18),0 4px 14px rgba(0,0,0,.45)}
.brand-mark svg{width:17px;height:17px;fill:var(--cyan);filter:drop-shadow(0 0 6px rgba(79,227,255,.6))}
.brand-copy{display:grid;grid-template-columns:auto auto;align-items:baseline;column-gap:1px;line-height:1}
.brand-copy b{font-size:17px;font-weight:900;letter-spacing:.02em;font-style:italic}
.brand-copy span{font-size:12px;font-weight:800;color:var(--pink);letter-spacing:.04em;font-style:italic}
.brand-copy em{grid-column:1/-1;font-style:normal;font-size:7.5px;letter-spacing:.26em;color:var(--dim);margin-top:3px;font-weight:700}
.hud-right{display:flex;align-items:center;gap:6px}
.wallet{display:flex;align-items:center;gap:4px;height:30px;padding:0 8px;border-radius:10px;background:rgba(11,15,24,.78);border:1px solid var(--line);box-shadow:inset 0 1px 0 rgba(255,255,255,.06);backdrop-filter:blur(10px)}
.wallet b{font-size:12px;font-weight:800;letter-spacing:.01em;font-variant-numeric:tabular-nums;white-space:nowrap}
.wallet em{font-style:normal;font-size:8px;font-weight:800;color:var(--dim);letter-spacing:.08em;margin-left:-1px}
.cur-dot{width:6px;height:6px;border-radius:50%;background:var(--gold);box-shadow:0 0 8px var(--gold)}
.cur-dot.sc{background:var(--cyan);box-shadow:0 0 8px var(--cyan)}
.wallet-scrap{padding-right:9px}
.hud-right .wallet:nth-child(2){background:rgba(8,18,24,.78)}
.hud-right .wallet:nth-child(2) b{color:#d6fbff}
.hud-right .wallet:nth-child(1) b{color:#fff0cc}
.icon-btn{width:32px;height:32px;border-radius:10px;display:grid;place-items:center;background:rgba(13,17,27,.8);border:1px solid var(--line);color:#cfd8e8;transition:transform .15s,background .15s}
.icon-btn:active{transform:scale(.92);background:rgba(30,38,55,.9)}
.icon-btn svg{width:15px;height:15px;fill:currentColor}
.icon-btn.small{width:30px;height:30px;font-size:12px;border-radius:9px}
@media(max-width:374px){
  .brand-copy em{display:none}
  .brand-copy b{font-size:15px}
  .brand-mark{width:27px;height:27px}
  .wallet{padding:0 6px;height:28px}
  .wallet b{font-size:11px}
  .wallet em{display:none}
  .hud{padding-left:10px;padding-right:10px;gap:6px}
  .hud-right{gap:4px}
}

/* panel system */
.panel-wrap{position:fixed;z-index:20;bottom:var(--tab-h);left:50%;transform:translateX(-50%);width:100%;max-width:var(--app-w);padding:0 8px;pointer-events:none}
.panel{
  display:none;pointer-events:auto;position:relative;
  max-height:41dvh;min-height:132px;
  border-radius:var(--radius) var(--radius) 0 0;
  background:linear-gradient(178deg,rgba(22,28,42,.9),rgba(9,12,20,.94) 58%,rgba(6,8,14,.97));
  border:1px solid rgba(255,255,255,.11);border-bottom:0;
  box-shadow:0 -18px 60px rgba(0,0,0,.55),inset 0 1px 0 rgba(255,255,255,.15);
  backdrop-filter:blur(22px) saturate(145%);
  -webkit-backdrop-filter:blur(22px) saturate(145%);
  overflow:hidden;
}
.panel::before{content:"";position:absolute;left:10%;right:10%;top:0;height:1px;background:linear-gradient(90deg,transparent,rgba(255,255,255,.6),transparent);pointer-events:none}
.panel::after{content:"";position:absolute;inset:0;pointer-events:none;border-radius:inherit;background:radial-gradient(100% 40% at 50% 0%,rgba(79,227,255,.055),transparent 70%)}
.panel.active{display:flex;flex-direction:column;animation:panelIn .34s cubic-bezier(.2,.8,.2,1)}
@keyframes panelIn{from{transform:translateY(14px);opacity:.4}to{transform:translateY(0);opacity:1}}
.panel[data-panel="garage"]{max-height:48dvh}
.panel[data-panel="workshop"]{max-height:53dvh}
.panel[data-panel="race"]{max-height:52dvh}
.panel[data-panel="wheel"]{max-height:46dvh}
.panel-grip{width:38px;height:4px;border-radius:4px;background:rgba(255,255,255,.18);margin:7px auto 0;flex:0 0 auto}
.panel-scroll{overflow-y:auto;overscroll-behavior:contain;touch-action:pan-y;-webkit-overflow-scrolling:touch;padding:8px 14px calc(10px + env(safe-area-inset-bottom,0px));scrollbar-width:none}
.panel-scroll::-webkit-scrollbar{display:none}
.panel-scroll.bottom-safe{padding-bottom:16px}

/* shared type + controls */
.eyebrow{font-size:8.5px;font-weight:800;letter-spacing:.2em;color:var(--dim);text-transform:uppercase;font-style:normal}
.section-head{display:flex;align-items:center;justify-content:space-between;gap:8px;margin:2px 0 9px}
.section-title{display:flex;align-items:center;gap:7px;font-size:13px;font-weight:900;letter-spacing:.11em;text-transform:uppercase}
.section-title .tick{width:3px;height:13px;border-radius:2px;background:linear-gradient(180deg,var(--cyan),var(--pink));box-shadow:0 0 9px rgba(79,227,255,.65)}
.section-sub{font-size:9px;color:var(--muted);letter-spacing:.08em}
.muted{color:var(--muted)}
.tiny{font-size:9px}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:42px;padding:0 16px;border-radius:13px;font-size:11px;font-weight:900;letter-spacing:.12em;text-transform:uppercase;border:1px solid var(--line-2);background:rgba(255,255,255,.055);color:var(--ink);transition:transform .14s,filter .14s,box-shadow .14s;position:relative;overflow:hidden}
.btn:active{transform:scale(.965)}
.btn[disabled]{opacity:.38;pointer-events:none;filter:grayscale(.4)}
.btn-primary{background:linear-gradient(135deg,#ff3d86,#c21dff 58%,#6b2cff);border-color:rgba(255,255,255,.22);box-shadow:0 8px 26px rgba(216,35,255,.28),inset 0 1px 0 rgba(255,255,255,.42)}
.btn-primary::after{content:"";position:absolute;inset:0;background:linear-gradient(110deg,transparent 25%,rgba(255,255,255,.3) 45%,transparent 60%);transform:translateX(-120%);animation:sheen 3.6s ease-in-out infinite}
@keyframes sheen{0%,55%{transform:translateX(-120%)}80%,100%{transform:translateX(120%)}}
.btn-gold{background:linear-gradient(135deg,#ffe08a,#ffb020 55%,#ff7a1a);border-color:rgba(255,255,255,.35);color:#241400;box-shadow:0 8px 24px rgba(255,176,32,.26),inset 0 1px 0 rgba(255,255,255,.6)}
.btn-cyan{background:linear-gradient(135deg,#3fe6ff,#1877ff);border-color:rgba(255,255,255,.28);color:#00121a;box-shadow:0 8px 24px rgba(45,180,255,.25),inset 0 1px 0 rgba(255,255,255,.5)}
.btn-ghost{background:rgba(255,255,255,.045);border-color:var(--line)}
.btn-block{width:100%}
.btn-lg{min-height:54px;border-radius:16px;font-size:13px;letter-spacing:.16em}
.btn-sm{min-height:34px;padding:0 11px;font-size:9px;border-radius:9px;letter-spacing:.1em}
.btn-mini{min-height:30px;padding:0 10px;font-size:9px;border-radius:8px;letter-spacing:.08em}
.btn .sub{font-size:8px;letter-spacing:.08em;color:rgba(255,255,255,.65);font-weight:700}
.btn-gold .sub{color:rgba(36,20,0,.62)}
.btn-icon-only{width:42px;padding:0}
.chip{display:inline-flex;align-items:center;gap:5px;height:27px;padding:0 10px;border-radius:999px;background:rgba(255,255,255,.045);border:1px solid var(--line);font-size:9px;font-weight:800;letter-spacing:.08em;color:var(--muted);text-transform:uppercase;white-space:nowrap;transition:.15s}
.chip.active{color:#041014;background:linear-gradient(135deg,#7ff1ff,#36b7ff);border-color:transparent;box-shadow:0 4px 16px rgba(79,227,255,.24)}
.chip:active{transform:scale(.95)}
.pill{display:inline-flex;align-items:center;gap:4px;height:22px;padding:0 8px;border-radius:999px;background:rgba(255,255,255,.06);font-size:8px;font-weight:800;letter-spacing:.08em;color:var(--muted);text-transform:uppercase;border:1px solid rgba(255,255,255,.06)}
.toggle{display:flex;align-items:center;gap:8px;font-size:9px;font-weight:800;letter-spacing:.1em;color:var(--muted);text-transform:uppercase;cursor:pointer;user-select:none}
.toggle input{position:absolute;opacity:0;pointer-events:none}
.toggle .track{position:relative;width:34px;height:19px;border-radius:20px;background:rgba(255,255,255,.11);border:1px solid var(--line);transition:.22s;box-shadow:inset 0 2px 4px rgba(0,0,0,.4)}
.toggle .track::after{content:"";position:absolute;top:2px;left:2px;width:13px;height:13px;border-radius:50%;background:#aab4c7;transition:.22s cubic-bezier(.2,.8,.2,1)}
.toggle input:checked + .track{background:linear-gradient(90deg,#18d98d,#5affc0);border-color:transparent;box-shadow:0 0 14px rgba(67,255,163,.35)}
.toggle input:checked + .track::after{left:17px;background:#04180e;box-shadow:0 1px 3px rgba(0,0,0,.4)}
.toggle input:checked ~ .toggle-lbl{color:var(--green)}
.online-dot{width:5px;height:5px;border-radius:50%;background:var(--green);box-shadow:0 0 8px var(--green)}
.meter{height:5px;border-radius:4px;background:rgba(255,255,255,.09);overflow:hidden;position:relative}
.meter>i{display:block;height:100%;border-radius:inherit;background:linear-gradient(90deg,#3dd6ff,#9c6bff);box-shadow:0 0 8px rgba(79,227,255,.5);transition:width .3s}
.meter.accel>i{background:linear-gradient(90deg,#ff9d3d,#ff3d86)}
.meter.grip>i{background:linear-gradient(90deg,#43ffa3,#1ab6ff)}
.meter.tiny{height:4px}
.badge{display:inline-flex;align-items:center;gap:4px;height:20px;padding:0 7px;border-radius:5px;font-size:8px;font-weight:900;letter-spacing:.09em;text-transform:uppercase;border:1px solid;background:rgba(0,0,0,.3)}
.badge.trait-hacker{color:#4dffab;border-color:rgba(67,255,163,.4);background:rgba(16,80,52,.32)}
.badge.trait-blackhole{color:#b995ff;border-color:rgba(157,107,255,.4);background:rgba(55,24,100,.34)}
.badge.trait-godly{color:#ffdd7d;border-color:rgba(255,194,71,.4);background:rgba(90,60,10,.3)}
.badge .bdot{width:5px;height:5px;border-radius:50%;background:currentColor;box-shadow:0 0 6px currentColor}
.rar-dot{width:7px;height:7px;border-radius:50%;flex:0 0 auto;box-shadow:0 0 8px currentColor;background:currentColor}
.r-stock{color:#aab5c5!important}
.r-street{color:#35e6ac!important}
.r-pro{color:#4fa6ff!important}
.r-prototype{color:#b47bff!important}
.r-apex{color:#ffc247!important}
.rline-stock{background:#aab5c5}.rline-street{background:#35e6ac}.rline-pro{background:#4fa6ff}.rline-prototype{background:#b47bff}.rline-apex{background:linear-gradient(90deg,#ffdd7d,#ff9d1f)}
.divider{height:1px;background:linear-gradient(90deg,transparent,var(--line),transparent);margin:10px 0}
.empty-note{padding:18px 12px;border-radius:14px;background:rgba(255,255,255,.03);border:1px dashed rgba(255,255,255,.12);text-align:center;color:var(--muted);font-size:10px;letter-spacing:.05em;line-height:1.6}
.empty-note b{color:var(--ink);display:block;font-size:12px;letter-spacing:.08em;margin-bottom:3px}
.scroll-x{display:flex;gap:8px;overflow-x:auto;overflow-y:hidden;touch-action:pan-x;scroll-snap-type:x proximity;scrollbar-width:none;padding:2px 2px 6px;margin:0 -2px}
.scroll-x::-webkit-scrollbar{display:none}
.scroll-x>*{scroll-snap-align:start;flex:0 0 auto}

/* RIP */
.rip-top{display:flex;align-items:center;justify-content:space-between;margin:0 0 7px}
.rip-title{display:flex;flex-direction:column;gap:1px}
.rip-title h2{font-size:14px;font-weight:900;letter-spacing:.14em;font-style:italic}
.rip-title span{font-size:8px;color:var(--muted);letter-spacing:.14em;text-transform:uppercase}
.rip-price{display:flex;flex-direction:column;align-items:flex-end;gap:1px}
.rip-price b{font-size:17px;font-weight:900;font-variant-numeric:tabular-nums;color:#ffe7a8;text-shadow:0 0 14px rgba(255,194,71,.35)}
.rip-price b small{font-size:8px;color:var(--dim);margin-left:2px}
.rip-price span{font-size:7.5px;color:var(--dim);letter-spacing:.14em}
.pack-strip{padding-bottom:8px}
.pack-card{width:104px;padding:0;border-radius:13px;overflow:hidden;background:#0b0f18;border:1px solid rgba(255,255,255,.1);text-align:left;position:relative;transition:transform .18s,border-color .18s,box-shadow .18s;flex:0 0 auto}
.pack-card:active{transform:scale(.96)}
.pack-card .pk-art{position:relative;height:70px;overflow:hidden;background:linear-gradient(140deg,var(--pk-a,#222),var(--pk-b,#080b12))}
.pack-card .pk-art::before{content:"";position:absolute;inset:0;background:
  linear-gradient(115deg,transparent 10%,rgba(255,255,255,.16) 42%,transparent 60%),
  radial-gradient(80% 110% at 80% 0%,rgba(255,255,255,.2),transparent 55%)}
.pack-card .pk-art::after{content:"";position:absolute;left:-20%;right:-20%;top:46%;height:1px;background:rgba(255,255,255,.2);transform:rotate(-14deg)}
.pack-card .pk-code{position:absolute;left:7px;top:7px;font-size:7px;font-weight:900;letter-spacing:.12em;color:rgba(255,255,255,.65);z-index:1}
.pack-card .pk-glyph{position:absolute;right:6px;bottom:2px;font-size:30px;font-weight:900;font-style:italic;letter-spacing:-.08em;color:rgba(255,255,255,.12);line-height:1;z-index:1;text-transform:uppercase}
.pack-card .pk-body{padding:6px 7px 7px;position:relative;z-index:1}
.pack-card .pk-name{font-size:8.5px;font-weight:900;letter-spacing:.02em;line-height:1.15;min-height:20px;text-transform:uppercase;color:#eef3ff}
.pack-card .pk-foot{display:flex;align-items:center;justify-content:space-between;margin-top:4px}
.pack-card .pk-cost{font-size:8.5px;font-weight:900;color:#ffe7a8;font-variant-numeric:tabular-nums}
.pack-card .pk-odds{display:flex;gap:2px}
.pack-card .pk-odds i{width:3px;height:7px;border-radius:1px;display:block}
.pack-card.selected{border-color:var(--pk-sel,#ff3d86);box-shadow:0 0 0 1px var(--pk-sel,#ff3d86),0 8px 22px rgba(0,0,0,.45),0 0 24px var(--pk-glow,rgba(255,61,134,.25));transform:translateY(-1px)}
.pack-card.selected::after{content:"";position:absolute;inset:0;border-radius:inherit;pointer-events:none;border:1px solid rgba(255,255,255,.26)}
.pack-card.selected .pk-name{color:#fff}
.odds-line{display:flex;align-items:center;justify-content:space-between;gap:4px;margin-top:1px}
.odds-line .odds-title{font-size:8px;letter-spacing:.16em;color:var(--dim);font-weight:800;text-transform:uppercase;white-space:nowrap}
.odds-chips{display:flex;gap:3px;flex:1;justify-content:flex-end;flex-wrap:wrap}
.odds-chip{display:flex;align-items:center;gap:3px;font-size:7px;font-weight:800;color:var(--muted);letter-spacing:.02em;white-space:nowrap;padding:2px 4px;border-radius:4px;background:rgba(255,255,255,.04)}
.odds-chip b{color:#e8eefc;font-size:7.5px;font-weight:900}
.rip-actions{display:flex;gap:8px;align-items:stretch;margin-top:8px}
.rip-actions .btn-primary{flex:1}
.rip-actions .auto-box{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;min-width:74px;padding:0 8px;border-radius:13px;background:rgba(255,255,255,.035);border:1px solid var(--line)}
.rip-actions .auto-box .toggle{font-size:7.5px;letter-spacing:.1em}
.auto-state{font-size:7px;letter-spacing:.1em;color:var(--dim);text-transform:uppercase}
.rip-meta{display:flex;align-items:center;justify-content:space-between;margin-top:5px;font-size:7.5px;color:var(--dim);letter-spacing:.08em}
.rip-meta b{color:#d8e2f5;font-weight:800}
.pity-note{display:flex;align-items:center;gap:4px}
.reveal-tag{
  position:fixed;z-index:28;left:50%;top:calc(56px + env(safe-area-inset-top,0px) + 10px);
  transform:translateX(-50%);display:flex;align-items:center;gap:8px;
  padding:7px 14px 7px 8px;border-radius:999px;
  background:rgba(8,11,19,.82);border:1px solid var(--line-2);
  backdrop-filter:blur(14px);box-shadow:0 12px 34px rgba(0,0,0,.5);
  animation:tagIn .35s cubic-bezier(.2,.8,.2,1);pointer-events:none;max-width:calc(100% - 30px)
}
.reveal-tag[hidden]{display:none}
.reveal-tag .rt-badge{display:grid;place-items:center;width:38px;height:38px;border-radius:10px;font-size:8px;font-weight:900;letter-spacing:.04em;text-align:center;line-height:1.05;border:1px solid;background:rgba(0,0,0,.35)}
.reveal-tag .rt-copy{display:flex;flex-direction:column;gap:2px;min-width:0}
.reveal-tag .rt-copy b{font-size:12px;font-weight:900;letter-spacing:.04em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:190px}
.reveal-tag .rt-copy span{font-size:8px;letter-spacing:.1em;color:var(--muted);text-transform:uppercase;white-space:nowrap}
.reveal-tag .rt-new{font-size:9px;font-weight:900;letter-spacing:.08em;color:#041310;background:var(--green);padding:3px 7px;border-radius:5px}
.reveal-tag .rt-dup{font-size:9px;font-weight:900;letter-spacing:.08em;color:#0a1520;background:var(--cyan);padding:3px 7px;border-radius:5px}
@keyframes tagIn{from{opacity:0;transform:translate(-50%,-8px) scale(.94)}to{opacity:1;transform:translate(-50%,0) scale(1)}}

/* GARAGE */
.filter-row{display:flex;gap:5px;overflow-x:auto;scrollbar-width:none;padding:1px 0 7px;touch-action:pan-x}
.filter-row::-webkit-scrollbar{display:none}
.filter-row .chip{flex:0 0 auto;height:25px;padding:0 9px;font-size:8px}
.roster{display:flex;gap:7px;overflow-x:auto;scrollbar-width:none;padding:1px 1px 8px;touch-action:pan-x;scroll-snap-type:x proximity}
.roster::-webkit-scrollbar{display:none}
.car-card{width:116px;flex:0 0 auto;border-radius:12px;background:linear-gradient(155deg,rgba(255,255,255,.075),rgba(255,255,255,.022));border:1px solid var(--line);overflow:hidden;text-align:left;position:relative;scroll-snap-align:start;transition:transform .16s,border-color .16s}
.car-card:active{transform:scale(.96)}
.car-card.locked{opacity:.62}
.car-card.selected{border-color:var(--rar,#fff);box-shadow:0 0 0 1px var(--rar,#fff),0 6px 18px rgba(0,0,0,.4)}
.car-card .cc-top{height:54px;position:relative;background:linear-gradient(160deg,var(--rar-soft,rgba(255,255,255,.1)),rgba(4,6,12,.2) 70%);overflow:hidden;display:grid;place-items:center}
.car-card .cc-top::after{content:"";position:absolute;inset:0;background:linear-gradient(110deg,transparent 30%,rgba(255,255,255,.1) 47%,transparent 58%)}
.car-card .cc-car{width:86px;height:34px;filter:drop-shadow(0 4px 7px rgba(0,0,0,.6))}
.car-card .cc-rar{position:absolute;left:5px;top:5px;display:flex;align-items:center;gap:3px;font-size:6px;font-weight:900;letter-spacing:.08em;text-transform:uppercase;color:var(--rar,#fff);background:rgba(4,6,12,.55);padding:2px 4px;border-radius:3px;border:1px solid rgba(255,255,255,.1)}
.car-card .cc-trait{position:absolute;right:4px;top:4px;font-size:6px;padding:2px 4px;border-radius:3px;font-weight:900;letter-spacing:.05em}
.car-card .cc-body{padding:6px 7px 7px}
.car-card .cc-name{font-size:9px;font-weight:900;letter-spacing:.01em;line-height:1.1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;text-transform:uppercase}
.car-card .cc-stats{display:flex;gap:2px;margin-top:5px}
.car-card .cc-stat{flex:1;height:3px;border-radius:2px;background:rgba(255,255,255,.08);overflow:hidden}
.car-card .cc-stat i{display:block;height:100%;background:var(--rar,#fff);border-radius:2px}
.car-card .cc-foot{display:flex;align-items:center;justify-content:space-between;margin-top:5px;font-size:6.5px;color:var(--dim);letter-spacing:.04em}
.car-card .cc-foot b{color:#dfe8fa;font-weight:800}
.car-card .bp-chip{color:#9ff2ff}
.garage-note{display:flex;align-items:center;justify-content:space-between;margin:1px 0 7px;font-size:8px;color:var(--dim);letter-spacing:.06em}
.garage-note b{color:#dbe6fb}
.showcase-chips{display:flex;gap:3px}

/* WORKSHOP */
.ws-head{display:flex;align-items:center;gap:9px;margin:1px 0 8px}
.ws-thumb{width:46px;height:35px;border-radius:8px;background:linear-gradient(145deg,var(--rar-soft,rgba(255,255,255,.1)),rgba(0,0,0,.3));border:1px solid var(--line);display:grid;place-items:center;flex:0 0 auto}
.ws-thumb svg{width:40px;height:20px}
.ws-copy{min-width:0;flex:1}
.ws-copy b{display:block;font-size:12px;font-weight:900;letter-spacing:.02em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ws-copy span{display:flex;align-items:center;gap:4px;font-size:7.5px;color:var(--muted);letter-spacing:.06em;margin-top:2px}
.ws-level{text-align:right;font-size:7px;color:var(--dim);letter-spacing:.08em;line-height:1.4}
.ws-level b{display:block;font-size:14px;color:#e9f0ff;letter-spacing:0}
.upgrade-list{display:flex;flex-direction:column;gap:6px}
.upgrade-row{display:flex;align-items:center;gap:8px;padding:6px 7px 6px 9px;border-radius:11px;background:rgba(255,255,255,.035);border:1px solid var(--line)}
.upgrade-row.maxed{background:rgba(255,194,71,.05);border-color:rgba(255,194,71,.18)}
.up-label{width:52px;flex:0 0 auto}
.up-label b{display:block;font-size:8.5px;font-weight:900;letter-spacing:.12em;text-transform:uppercase}
.up-label span{display:block;font-size:7px;color:var(--dim);margin-top:1px;letter-spacing:.03em}
.up-mid{flex:1;min-width:0}
.up-meter{margin-bottom:3px}
.up-nums{display:flex;justify-content:space-between;font-size:6.5px;color:var(--dim);letter-spacing:.03em}
.up-nums b{color:#d9e2f3;font-weight:800}
.up-nums b.hot{color:var(--cyan)}
.up-btn{min-width:62px;min-height:36px;padding:0 7px;border-radius:8px;font-size:7px;line-height:1.15;display:flex;flex-direction:column;gap:1px;align-items:center;justify-content:center;letter-spacing:.05em;background:linear-gradient(145deg,rgba(255,255,255,.1),rgba(255,255,255,.03));border:1px solid var(--line-2)}
.up-btn b{font-size:9px;font-weight:900;color:#ffe6a3}
.up-btn span{font-size:6.5px;color:var(--muted);white-space:nowrap}
.up-btn:disabled{opacity:.4}
.up-btn:active{transform:scale(.95)}
.ws-links{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-top:8px}
.ws-link{display:flex;align-items:center;gap:7px;padding:7px 9px;border-radius:10px;background:rgba(255,255,255,.035);border:1px solid var(--line);text-align:left;min-height:42px}
.ws-link:active{transform:scale(.97)}
.ws-link .li{width:24px;height:24px;border-radius:7px;display:grid;place-items:center;background:rgba(79,227,255,.1);color:var(--cyan);font-size:12px;flex:0 0 auto}
.ws-link.vault .li{color:var(--gold);background:rgba(255,194,71,.1)}
.ws-link .lc{min-width:0}
.ws-link .lc b{display:block;font-size:8px;font-weight:900;letter-spacing:.11em}
.ws-link .lc span{display:block;font-size:6.5px;color:var(--dim);margin-top:1px;white-space:nowrap}
.ws-link .la{margin-left:auto;color:var(--dim);font-size:12px}

/* RACE */
.track-card{width:125px;flex:0 0 auto;border-radius:11px;overflow:hidden;background:#0a0e17;border:1px solid var(--line);text-align:left;transition:transform .16s,border-color .16s;position:relative}
.track-card:active{transform:scale(.96)}
.track-card .tk-art{height:46px;position:relative;background:linear-gradient(135deg,var(--t1,#222),var(--t2,#05070c));overflow:hidden}
.track-card .tk-art::after{content:"";position:absolute;inset:0;background:linear-gradient(100deg,transparent 35%,rgba(255,255,255,.13) 48%,transparent 58%)}
.track-card .tk-glyph{position:absolute;left:6px;bottom:-4px;font-size:27px;font-weight:900;font-style:italic;letter-spacing:-.08em;color:rgba(255,255,255,.17);line-height:1}
.track-card .tk-num{position:absolute;right:5px;top:4px;font-size:6px;letter-spacing:.12em;color:rgba(255,255,255,.55);font-weight:900}
.track-card .tk-body{padding:5px 7px 7px}
.track-card .tk-name{font-size:8px;font-weight:900;letter-spacing:.01em;line-height:1.15;min-height:20px;text-transform:uppercase}
.track-card .tk-meta{display:flex;align-items:center;justify-content:space-between;margin-top:3px;font-size:6.5px;color:var(--dim);letter-spacing:.03em}
.track-card .tk-meta b{color:#ffe0a0;font-weight:900;font-variant-numeric:tabular-nums}
.track-card.selected{border-color:var(--tacc,#ff3d86);box-shadow:0 0 0 1px var(--tacc,#ff3d86),0 0 18px rgba(255,61,134,.2)}
.track-card .tk-diff{display:flex;gap:2px}
.track-card .tk-diff i{width:4px;height:4px;border-radius:50%;background:rgba(255,255,255,.16)}
.track-card .tk-diff i.on{background:var(--tacc,#ff3d86);box-shadow:0 0 5px var(--tacc)}
.race-info{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:2px}
.race-info .race-loc{min-width:0}
.race-info .race-loc b{display:block;font-size:11px;font-weight:900;letter-spacing:.06em;text-transform:uppercase;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.race-info .race-loc span{font-size:7.5px;color:var(--muted);letter-spacing:.05em}
.race-launch{display:flex;gap:7px;align-items:center;margin-top:8px}
.race-launch .btn-primary{flex:1}
.race-best{text-align:right;min-width:58px}
.race-best span{display:block;font-size:6.5px;color:var(--dim);letter-spacing:.08em}
.race-best b{display:block;font-size:11px;color:#eaf1ff;font-variant-numeric:tabular-nums;letter-spacing:.02em}
.race-hud{position:fixed;z-index:24;left:50%;transform:translateX(-50%);width:100%;max-width:var(--app-w);top:calc(52px + env(safe-area-inset-top,0px));padding:0 14px;pointer-events:none}
.race-hud[hidden]{display:none}
.race-hud-top{display:flex;gap:6px}
.race-pill{flex:1;display:flex;align-items:baseline;justify-content:center;gap:4px;height:36px;border-radius:10px;background:rgba(7,10,17,.7);border:1px solid var(--line);backdrop-filter:blur(10px);box-shadow:inset 0 1px 0 rgba(255,255,255,.08)}
.race-pill span{font-size:6.5px;color:var(--dim);letter-spacing:.13em;font-weight:800}
.race-pill b{font-size:15px;font-weight:900;font-variant-numeric:tabular-nums;color:#f1f6ff;letter-spacing:.01em}
.race-pill em{font-size:6.5px;font-style:normal;color:var(--dim);letter-spacing:.04em}
.race-pill:nth-child(1) b{color:var(--gold)}
.race-progress{margin-top:7px;padding:8px 10px 6px;border-radius:11px;background:rgba(7,10,17,.66);border:1px solid var(--line);backdrop-filter:blur(10px)}
.race-track-line{height:5px;border-radius:4px;background:rgba(255,255,255,.1);position:relative;overflow:visible}
.race-track-line>span{display:block;height:100%;width:0%;border-radius:4px;background:linear-gradient(90deg,#47e0ff,#ff3d86);box-shadow:0 0 8px rgba(255,61,134,.5);transition:width .12s linear}
.race-track-line #race-progress-dot{position:absolute;top:50%;left:0%;width:9px;height:9px;border-radius:50%;background:#fff;border:2px solid var(--pink);transform:translate(-50%,-50%);box-shadow:0 0 10px var(--pink);transition:left .12s linear}
.race-track-line .rail-start,.race-track-line .rail-end{position:absolute;top:-2px;width:1px;height:9px;background:rgba(255,255,255,.3)}
.rail-start{left:0}.rail-end{right:0}
.race-progress-labels{display:flex;justify-content:space-between;font-size:6.5px;color:var(--dim);letter-spacing:.08em;margin-top:5px;text-transform:uppercase}
.race-progress-labels span:first-child{color:#c8d6ef;font-weight:800}
.race-lane-controls{position:fixed;z-index:26;left:50%;transform:translateX(-50%);bottom:calc(var(--tab-h) + 12px);width:100%;max-width:var(--app-w);padding:0 16px;display:flex;align-items:center;justify-content:space-between;gap:10px}
.race-lane-controls .lane-btn{width:44px;height:44px;border-radius:50%;display:grid;place-items:center;background:rgba(9,13,21,.72);border:1px solid var(--line-2);color:#dce8ff;font-size:24px;line-height:0;backdrop-filter:blur(10px);box-shadow:inset 0 1px 0 rgba(255,255,255,.1)}
.race-lane-controls .lane-btn:active{transform:scale(.92);background:rgba(255,255,255,.14)}
.nitro-btn{position:relative;width:118px;height:62px;border-radius:20px;background:linear-gradient(160deg,#18e0ff,#1577ff 55%,#0b3ec4);border:1px solid rgba(255,255,255,.42);box-shadow:0 10px 34px rgba(21,142,255,.42),inset 0 2px 0 rgba(255,255,255,.55),inset 0 -8px 16px rgba(0,0,20,.32);overflow:hidden;color:#031018}
.nitro-btn:active{transform:scale(.95)}
.nitro-btn .nitro-ice{position:absolute;inset:0;background:linear-gradient(110deg,transparent 20%,rgba(255,255,255,.4) 40%,transparent 55%);transform:translateX(-110%);animation:sheen 2.6s infinite}
.nitro-btn .nitro-content{display:flex;flex-direction:column;align-items:center;gap:1px;position:relative;z-index:1;padding-bottom:7px}
.nitro-btn .nitro-content b{font-size:15px;font-weight:900;letter-spacing:.16em;font-style:italic}
.nitro-btn .nitro-content em{font-size:6.5px;font-style:normal;font-weight:900;letter-spacing:.13em;opacity:.62}
.nitro-btn .nitro-gauge{position:absolute;left:7px;right:7px;bottom:6px;height:4px;border-radius:3px;background:rgba(0,20,40,.35);overflow:hidden;z-index:1}
.nitro-btn .nitro-gauge span{display:block;height:100%;width:100%;border-radius:3px;background:linear-gradient(90deg,#c9fff0,#fff);transition:width .08s linear}
.nitro-btn.ready{animation:nitroPulse 1.8s ease-in-out infinite}
@keyframes nitroPulse{0%,100%{box-shadow:0 10px 28px rgba(21,142,255,.32),inset 0 2px 0 rgba(255,255,255,.5)}50%{box-shadow:0 10px 40px rgba(79,227,255,.7),inset 0 2px 0 rgba(255,255,255,.6)}}
.nitro-btn.empty{filter:grayscale(.55) brightness(.72)}
.race-hint{position:fixed;z-index:25;left:50%;transform:translateX(-50%);bottom:calc(var(--tab-h) + 80px);font-size:7px;letter-spacing:.16em;color:rgba(255,255,255,.4);text-transform:uppercase;white-space:nowrap;pointer-events:none}
.race-fx{position:fixed;inset:0;z-index:23;pointer-events:none;background:radial-gradient(circle at 50% 60%,transparent 40%,rgba(255,61,134,.22));opacity:0;transition:opacity .2s}
.race-fx.on{opacity:1}
.race-count{position:fixed;z-index:35;left:50%;top:38%;transform:translate(-50%,-50%);font-size:92px;font-style:italic;font-weight:900;letter-spacing:-.06em;color:#fff;text-shadow:0 0 40px rgba(79,227,255,.8),0 10px 30px #000;pointer-events:none;animation:countPop .9s ease-out}
.race-count.go{color:#cafff4;font-size:66px;letter-spacing:.02em;text-shadow:0 0 40px rgba(67,255,163,.9)}
@keyframes countPop{0%{transform:translate(-50%,-50%) scale(1.7);opacity:0}18%{opacity:1}100%{transform:translate(-50%,-50%) scale(.96);opacity:0}}

/* WHEEL */
.wheel-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:5px;margin:6px 0 8px}
.reward-tile{border-radius:9px;padding:5px 4px;background:rgba(255,255,255,.035);border:1px solid var(--line);text-align:center;min-height:38px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px}
.reward-tile b{font-size:9px;font-weight:900;color:#ffe6a3;font-variant-numeric:tabular-nums}
.reward-tile span{font-size:6px;color:var(--dim);letter-spacing:.06em;text-transform:uppercase}
.reward-tile.bp b{color:#8cecff}.reward-tile.core b{color:#c7a2ff}.reward-tile.scrap b{color:#9dffd0}
.offline-card{display:flex;align-items:center;gap:9px;padding:8px 9px;border-radius:12px;background:linear-gradient(135deg,rgba(79,227,255,.09),rgba(157,107,255,.06));border:1px solid rgba(79,227,255,.2);margin-bottom:7px}
.offline-icon{width:34px;height:34px;border-radius:10px;background:rgba(79,227,255,.12);display:grid;place-items:center;color:var(--cyan);flex:0 0 auto}
.offline-icon svg{width:18px;height:18px;fill:currentColor}
.offline-copy{flex:1;min-width:0}
.offline-copy b{display:block;font-size:9px;font-weight:900;letter-spacing:.1em;text-transform:uppercase}
.offline-copy span{display:block;font-size:7px;color:var(--muted);margin-top:2px;letter-spacing:.03em}
.offline-copy span em{font-style:normal;color:#c8f6ff;font-weight:800}
.offline-card .btn{min-height:34px;padding:0 11px;font-size:8px;border-radius:9px}
.spin-row{display:flex;gap:7px;align-items:center}
.spin-row .btn-primary{flex:1}
.spin-cost{text-align:right;min-width:64px}
.spin-cost span{display:block;font-size:6.5px;color:var(--dim);letter-spacing:.08em}
.spin-cost b{display:block;font-size:11px;color:#ffe6a3;font-weight:900;font-variant-numeric:tabular-nums}
.spin-cost b.free{color:var(--green)}
.wheel-note{display:flex;justify-content:space-between;align-items:center;margin-top:5px;font-size:7px;color:var(--dim);letter-spacing:.04em}
.wheel-note b{color:#ccd9ef}

/* tabs */
.tabs{position:fixed;z-index:40;bottom:0;left:50%;transform:translateX(-50%);width:100%;max-width:var(--app-w);height:var(--tab-h);padding:0 5px env(safe-area-inset-bottom,0px);display:grid;grid-template-columns:repeat(5,1fr);background:linear-gradient(180deg,rgba(9,12,20,.82),rgba(5,7,12,.97) 40%);border-top:1px solid rgba(255,255,255,.1);backdrop-filter:blur(24px) saturate(145%);-webkit-backdrop-filter:blur(24px) saturate(145%);box-shadow:0 -12px 36px rgba(0,0,0,.45)}
.tabs::before{content:"";position:absolute;left:12%;right:12%;top:0;height:1px;background:linear-gradient(90deg,transparent,rgba(255,255,255,.38),transparent)}
.tab{position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;height:62px;color:#59637a;transition:color .18s;border-radius:12px}
.tab .tab-ico{width:22px;height:22px;display:grid;place-items:center;transition:transform .2s}
.tab .tab-ico svg{width:19px;height:19px;fill:currentColor;stroke:currentColor;stroke-width:1.1;fill-rule:evenodd;stroke-linejoin:round;stroke-linecap:round}
.tab .tab-lbl{font-size:7.5px;font-weight:900;letter-spacing:.1em}
.tab .tab-glow{position:absolute;top:4px;width:28px;height:3px;border-radius:3px;background:transparent}
.tab:active .tab-ico{transform:scale(.9)}
.tab.active{color:#eaf6ff}
.tab.active .tab-ico{transform:translateY(-1px);filter:drop-shadow(0 0 7px rgba(79,227,255,.6))}
.tab.active .tab-glow{background:linear-gradient(90deg,var(--pink),var(--cyan));box-shadow:0 0 10px rgba(79,227,255,.6)}
.tab.active .tab-lbl{color:#fff}

/* sheets + modal */
.sheet-layer{position:fixed;inset:0;z-index:60;display:flex;align-items:flex-end;justify-content:center}
.sheet-layer[hidden]{display:none}
.sheet-backdrop{position:absolute;inset:0;background:rgba(2,3,7,.62);backdrop-filter:blur(3px);animation:fadeIn .2s}
@keyframes fadeIn{from{opacity:0}to{opacity:1}}
.sheet{position:relative;width:100%;max-width:var(--app-w);max-height:82dvh;display:flex;flex-direction:column;border-radius:24px 24px 0 0;background:linear-gradient(175deg,rgba(26,32,48,.98),rgba(9,12,20,.99));border:1px solid rgba(255,255,255,.14);border-bottom:0;box-shadow:0 -30px 80px rgba(0,0,0,.7),inset 0 1px 0 rgba(255,255,255,.2);animation:sheetUp .32s cubic-bezier(.2,.8,.2,1);padding-bottom:env(safe-area-inset-bottom,0px)}
@keyframes sheetUp{from{transform:translateY(40px);opacity:.5}to{transform:translateY(0);opacity:1}}
.sheet-grip{width:38px;height:4px;border-radius:4px;background:rgba(255,255,255,.2);margin:7px auto 0}
.sheet-head{display:flex;align-items:center;justify-content:space-between;padding:10px 16px 8px}
.sheet-head h3{font-size:13px;font-weight:900;letter-spacing:.14em}
.sheet-body{padding:2px 16px 20px;overflow-y:auto;overscroll-behavior:contain;touch-action:pan-y;scrollbar-width:none}
.sheet-body::-webkit-scrollbar{display:none}
.sheet-body p{font-size:10px;line-height:1.6;color:var(--muted)}
.sheet-actions{display:flex;gap:8px;margin-top:12px}
.sheet-actions .btn{flex:1}
.vault-summary{display:flex;gap:6px;margin-bottom:9px}
.vs-box{flex:1;padding:7px;border-radius:9px;background:rgba(255,255,255,.04);border:1px solid var(--line);text-align:center}
.vs-box b{display:block;font-size:14px;font-weight:900;color:#eaf4ff}
.vs-box span{display:block;font-size:6.5px;letter-spacing:.1em;color:var(--dim);text-transform:uppercase;margin-top:1px}
.vault-list{display:flex;flex-direction:column;gap:5px}
.vault-row{display:flex;align-items:center;gap:7px;padding:6px 7px;border-radius:9px;background:rgba(255,255,255,.03);border:1px solid var(--line)}
.vault-row .vr-dot{width:6px;height:6px;border-radius:50%;background:var(--rar);box-shadow:0 0 6px var(--rar);flex:0 0 auto}
.vault-row .vr-name{font-size:8.5px;font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}
.vault-row .vr-rar{font-size:6px;color:var(--dim);letter-spacing:.05em;text-transform:uppercase;margin-top:1px}
.vault-row .vr-count{font-size:9px;font-weight:900;color:#9fefff;margin-left:auto;white-space:nowrap}
.vault-row .vr-count.scrap{color:#9dffd0}
.vault-row .btn{min-height:26px;padding:0 7px;font-size:6.5px;border-radius:6px}
.fusion-box{padding:10px;border-radius:12px;background:linear-gradient(150deg,rgba(157,107,255,.12),rgba(255,255,255,.02));border:1px solid rgba(157,107,255,.24);margin-bottom:9px}
.fusion-box .fb-top{display:flex;align-items:center;justify-content:space-between;margin-bottom:6px}
.fusion-box .fb-top b{font-size:10px;font-weight:900;letter-spacing:.1em}
.fusion-box .fb-top span{font-size:7px;color:var(--dim);letter-spacing:.05em}
.fusion-box p{font-size:8px;line-height:1.5;color:var(--muted);margin-bottom:8px}
.fusion-recipe{display:flex;align-items:center;gap:5px;justify-content:center;margin:7px 0;font-size:8px;font-weight:800;color:#cbb8ff;letter-spacing:.04em}
.fusion-recipe i{font-style:normal;color:var(--dim)}
.fusion-recipe .fr-item{padding:3px 6px;border-radius:5px;background:rgba(157,107,255,.12);border:1px solid rgba(157,107,255,.2);white-space:nowrap;font-size:7px}
.fusion-cars{display:flex;flex-direction:column;gap:5px;max-height:170px;overflow:auto;scrollbar-width:none;margin-bottom:8px}
.fusion-cars::-webkit-scrollbar{display:none}
.fusion-car{display:flex;align-items:center;gap:7px;padding:5px 7px;border-radius:8px;background:rgba(255,255,255,.03);border:1px solid var(--line);font-size:8px;text-align:left;width:100%}
.fusion-car.active{background:rgba(157,107,255,.12);border-color:rgba(157,107,255,.34)}
.fusion-car b{font-size:8px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;flex:1;text-align:left}
.fusion-car span{font-size:7px;color:#cbb8ff;font-weight:800}
.modal-layer{position:fixed;inset:0;z-index:70;display:grid;place-items:center;padding:18px}
.modal-layer[hidden]{display:none}
.modal-backdrop{position:absolute;inset:0;background:rgba(2,3,7,.78);backdrop-filter:blur(8px);animation:fadeIn .2s}
.modal{position:relative;width:min(360px,100%);border-radius:22px;background:linear-gradient(160deg,rgba(29,36,54,.99),rgba(8,11,19,.99));border:1px solid rgba(255,255,255,.16);box-shadow:0 30px 90px rgba(0,0,0,.8),inset 0 1px 0 rgba(255,255,255,.22);padding:18px;animation:modalIn .3s cubic-bezier(.2,.9,.2,1);max-height:86dvh;overflow-y:auto;scrollbar-width:none}
.modal::-webkit-scrollbar{display:none}
@keyframes modalIn{from{transform:scale(.92) translateY(10px);opacity:0}to{transform:scale(1) translateY(0);opacity:1}}
.result-kicker{font-size:8px;letter-spacing:.25em;color:var(--dim);text-align:center;font-weight:800}
.result-place{font-size:52px;line-height:1;font-weight:900;font-style:italic;text-align:center;margin:6px 0 0;letter-spacing:-.04em;background:linear-gradient(180deg,#fff,#bcd2ff 50%,#6f8ec9);-webkit-background-clip:text;background-clip:text;color:transparent;filter:drop-shadow(0 6px 18px rgba(79,227,255,.2))}
.result-place.gold{background:linear-gradient(180deg,#fff6cf,#ffca4a 50%,#ff8a14);-webkit-background-clip:text;background-clip:text;color:transparent;filter:drop-shadow(0 6px 22px rgba(255,194,71,.35))}
.result-sub{text-align:center;font-size:9px;color:var(--muted);letter-spacing:.14em;text-transform:uppercase;margin-top:2px}
.result-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:5px;margin:14px 0 10px}
.result-stat{padding:7px 4px;border-radius:9px;background:rgba(255,255,255,.04);border:1px solid var(--line);text-align:center}
.result-stat b{display:block;font-size:13px;font-weight:900;color:#f2f7ff;font-variant-numeric:tabular-nums}
.result-stat span{display:block;font-size:6.5px;color:var(--dim);letter-spacing:.09em;text-transform:uppercase;margin-top:1px}
.result-rewards{border-radius:11px;background:rgba(255,194,71,.055);border:1px solid rgba(255,194,71,.16);padding:8px 10px;margin-bottom:12px}
.result-reward-row{display:flex;align-items:center;justify-content:space-between;font-size:9px;padding:3px 0;color:var(--muted);letter-spacing:.04em}
.result-reward-row b{color:#ffe1a0;font-weight:900;font-size:10px}
.result-reward-row.bp b{color:#8cecff}
.result-actions{display:grid;grid-template-columns:1fr 1fr;gap:7px}
.result-actions .btn{min-height:44px;font-size:9px}
.settings-list{display:flex;flex-direction:column;gap:7px}
.settings-row{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:8px 10px;border-radius:10px;background:rgba(255,255,255,.035);border:1px solid var(--line);min-height:48px}
.settings-row .sr-copy b{display:block;font-size:9px;font-weight:800;letter-spacing:.08em;text-transform:uppercase}
.settings-row .sr-copy span{display:block;font-size:7px;color:var(--dim);margin-top:2px}
.danger-btn{color:#ff9aa0;border-color:rgba(255,90,99,.25);background:rgba(255,90,99,.08)}
.save-meta{margin-top:10px;font-size:7px;color:var(--dim);line-height:1.6;letter-spacing:.03em;text-align:center}

/* inspect */
.inspect{position:fixed;inset:0;z-index:50;display:flex;flex-direction:column;justify-content:space-between;pointer-events:none}
.inspect[hidden]{display:none}
.inspect-top{position:relative;z-index:2;padding:calc(12px + env(safe-area-inset-top,0px)) 14px 0;display:flex;align-items:flex-start;justify-content:space-between;pointer-events:none}
.inspect-close{pointer-events:auto;background:rgba(8,11,17,.75);backdrop-filter:blur(10px)}
.inspect-hint{font-size:7px;letter-spacing:.2em;color:rgba(255,255,255,.34);padding:9px 10px;border-radius:8px;background:rgba(4,6,12,.4);border:1px solid rgba(255,255,255,.06);text-transform:uppercase}
.inspect-rarity{margin-left:auto;margin-right:8px;font-size:8px;font-weight:900;letter-spacing:.12em;text-transform:uppercase;padding:6px 9px;border-radius:7px;background:rgba(5,7,13,.6);border:1px solid var(--line)}
.inspect-bottom{position:relative;z-index:2;pointer-events:auto;background:linear-gradient(180deg,rgba(6,8,14,.15),rgba(6,8,14,.88) 22%,rgba(5,7,12,.98));padding:16px 16px calc(16px + env(safe-area-inset-bottom,0px));border-top:1px solid rgba(255,255,255,.08);backdrop-filter:blur(16px);margin-top:auto}
.inspect-head{display:flex;align-items:flex-end;justify-content:space-between;gap:8px;margin-bottom:8px}
.inspect-name{min-width:0}
.inspect-name .eyebrow{display:block;margin-bottom:2px}
.inspect-name h2{font-size:20px;font-weight:900;letter-spacing:-.01em;line-height:1.05;text-transform:uppercase}
.inspect-name .trait-line{display:flex;gap:4px;margin-top:5px;flex-wrap:wrap}
.inspect-badge{flex:0 0 auto;text-align:right;font-size:7px;color:var(--dim);letter-spacing:.1em}
.inspect-badge b{display:block;font-size:11px;color:#dceaff;letter-spacing:.04em;margin-top:2px}
.inspect-stats{display:flex;flex-direction:column;gap:5px;margin:10px 0 11px}
.inspect-stat{display:flex;align-items:center;gap:8px;font-size:8px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}
.inspect-stat .is-lbl{width:52px;flex:0 0 auto;font-weight:800;color:#aebbd0}
.inspect-stat .meter{flex:1}
.inspect-stat .is-val{width:54px;text-align:right;font-weight:900;color:#edf4ff;font-variant-numeric:tabular-nums;font-size:9px;white-space:nowrap}
.inspect-actions{display:flex;gap:7px}
.inspect-actions .btn{flex:1;min-height:46px}
.inspect-actions .btn-icon-only{flex:0 0 46px}

/* toasts */
.toasts{position:fixed;z-index:80;left:50%;transform:translateX(-50%);bottom:calc(var(--tab-h) + 12px);display:flex;flex-direction:column;gap:5px;align-items:center;pointer-events:none;width:100%;max-width:var(--app-w);padding:0 16px}
.toast{display:flex;align-items:center;gap:7px;max-width:100%;padding:7px 12px;border-radius:999px;background:rgba(11,15,24,.94);border:1px solid var(--line-2);box-shadow:0 8px 24px rgba(0,0,0,.5);font-size:9px;font-weight:700;letter-spacing:.03em;color:#e9f1ff;animation:toastIn .25s ease-out;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.toast b{color:var(--green);font-weight:900}
.toast.warn b{color:var(--gold)}
.toast .tic{width:6px;height:6px;border-radius:50%;background:var(--cyan);box-shadow:0 0 6px var(--cyan);flex:0 0 auto}
@keyframes toastIn{from{opacity:0;transform:translateY(8px) scale(.96)}to{opacity:1;transform:translateY(0) scale(1)}}
.toast.out{animation:toastOut .25s ease-in forwards}
@keyframes toastOut{to{opacity:0;transform:translateY(-4px);scale:.97}}

/* desktop constraints */
@media(min-width:700px){
  body{background:
    radial-gradient(60% 70% at 20% 20%,rgba(33,88,140,.14),transparent 60%),
    radial-gradient(50% 60% at 80% 80%,rgba(140,30,100,.12),transparent 60%),#020308}
  #app{box-shadow:0 0 0 1px rgba(255,255,255,.05),0 0 120px rgba(0,0,0,.8);max-width:var(--app-w);left:50%;transform:translateX(-50%);border-radius:0}
  .hud,.tabs,.panel-wrap,.race-hud,.race-lane-controls,.race-hint,.toasts{max-width:var(--app-w)}
}
@media(max-height:700px){
  .panel{max-height:38dvh}
  .panel[data-panel="garage"]{max-height:46dvh}
  .panel[data-panel="workshop"]{max-height:51dvh}
  .panel[data-panel="race"]{max-height:50dvh}
  .panel[data-panel="wheel"]{max-height:44dvh}
  .nitro-btn{width:108px;height:56px}
  .race-hint{bottom:calc(var(--tab-h) + 70px)}
  .tab{height:58px}
  :root{--tab-h:calc(62px + env(safe-area-inset-bottom,0px))}
}
@media(prefers-reduced-motion:reduce){
  *,*::before,*::after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}
}

