.scene-tint{position:absolute;inset:0;z-index:1;pointer-events:none;background:
  linear-gradient(180deg,rgba(3,4,10,.72) 0%,rgba(3,4,10,.1) 22%,transparent 46%,rgba(3,4,10,.2) 66%,rgba(3,4,10,.82) 100%)}
.vignette{position:absolute;inset:0;z-index:1;pointer-events:none;background:
  radial-gradient(105% 80% at 50% 42%,transparent 48%,rgba(0,0,0,.42) 100%)}

/* boot / fatal */
.boot{position:fixed;inset:0;z-index:90;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;background:radial-gradient(80% 60% at 50% 40%,#0a1020,#03040a 70%);transition:opacity .5s ease,visibility .5s}
.boot.done{opacity:0;visibility:hidden;pointer-events:none}
.boot-mark{display:flex;gap:5px;height:28px;align-items:flex-end;margin-bottom:4px}
.boot-mark span{width:6px;border-radius:2px;background:linear-gradient(180deg,var(--cyan),#1377ff);animation:bootbars .9s ease-in-out infinite alternate}
.boot-mark span:nth-child(1){height:14px;animation-delay:0s}
.boot-mark span:nth-child(2){height:28px;animation-delay:.12s;background:linear-gradient(180deg,var(--pink),#8b1dff)}
.boot-mark span:nth-child(3){height:20px;animation-delay:.24s}
@keyframes bootbars{to{transform:scaleY(.45);opacity:.5}}
.boot-title{font-size:30px;font-weight:900;letter-spacing:.16em;font-style:italic;text-shadow:0 0 30px rgba(79,227,255,.35)}
.boot-title span{color:var(--pink)}
.boot-sub{color:var(--muted);font-size:11px;letter-spacing:.22em;text-transform:uppercase}
.fatal{position:fixed;inset:0;z-index:100;display:grid;place-items:center;padding:24px;background:#03040a}
.fatal[hidden]{display:none}
.fatal-card{width:min(360px,100%);padding:24px;border-radius:22px;background:linear-gradient(160deg,#131a28,#0a0d15);border:1px solid var(--line-2);box-shadow:0 30px 80px #000}
.fatal-kicker{color:var(--danger);font-size:10px;letter-spacing:.24em;font-weight:800;margin-bottom:8px}
.fatal-card h2{font-size:24px;letter-spacing:-.02em;margin-bottom:8px}
.fatal-card p{color:var(--muted);font-size:13px;line-height:1.5;margin-bottom:18px}
.fatal-actions{display:flex;gap:10px}

/* HUD */
.hud{
  position:fixed;z-index:30;top:0;left:50%;transform:translateX(-50%);
  width:100%;max-width:var(--app-w);
  padding:calc(10px + env(safe-area-inset-top,0px)) 14px 8px;
  display:flex;align-items:center;justify-content:space-between;gap:10px;
  background:linear-gradient(180deg,rgba(3,4,10,.86),rgba(3,4,10,0));
  pointer-events:none;
}
.hud>*{pointer-events:auto}
.brand{display:flex;align-items:center;gap:8px;min-width:0}
.brand-mark{width:30px;height:30px;border-radius:9px;display:grid;place-items:center;background:linear-gradient(145deg,#1a2940,#0a0e18);border:1px solid rgba(79,227,255,.35);box-shadow:inset 0 1px 0 rgba(255,255,255,.18),0 4px 14px rgba(0,0,0,.45)}
.brand-mark svg{width:17px;height:17px;fill:var(--cyan);filter:drop-shadow(0 0 6px rgba(79,227,255,.6))}
.brand-copy{display:grid;grid-template-columns:auto auto;align-items:baseline;column-gap:1px;line-height:1}
.brand-copy b{font-size:17px;font-weight:900;letter-spacing:.02em;font-style:italic}
.brand-copy span{font-size:12px;font-weight:800;color:var(--pink);letter-spacing:.04em;font-style:italic}
.brand-copy em{grid-column:1/-1;font-style:normal;font-size:7.5px;letter-spacing:.26em;color:var(--dim);margin-top:3px;font-weight:700}
.hud-right{display:flex;align-items:center;gap:6px}
.wallet{display:flex;align-items:center;gap:4px;height:30px;padding:0 8px;border-radius:10px;background:rgba(11,15,24,.78);border:1px solid var(--line);box-shadow:inset 0 1px 0 rgba(255,255,255,.06);backdrop-filter:blur(10px)}
.wallet b{font-size:12px;font-weight:800;letter-spacing:.01em;font-variant-numeric:tabular-nums;white-space:nowrap}
.wallet em{font-style:normal;font-size:8px;font-weight:800;color:var(--dim);letter-spacing:.08em;margin-left:-1px}
.cur-dot{width:6px;height:6px;border-radius:50%;background:var(--gold);box-shadow:0 0 8px var(--gold)}
.cur-dot.sc{background:var(--cyan);box-shadow:0 0 8px var(--cyan)}
.wallet-scrap{padding-right:9px}
.hud-right .wallet:nth-child(2){background:rgba(8,18,24,.78)}
.hud-right .wallet:nth-child(2) b{color:#d6fbff}
.hud-right .wallet:nth-child(1) b{color:#fff0cc}
.icon-btn{width:32px;height:32px;border-radius:10px;display:grid;place-items:center;background:rgba(13,17,27,.8);border:1px solid var(--line);color:#cfd8e8;transition:transform .15s,background .15s}
.icon-btn:active{transform:scale(.92);background:rgba(30,38,55,.9)}
.icon-btn svg{width:15px;height:15px;fill:currentColor}
.icon-btn.small{width:30px;height:30px;font-size:12px;border-radius:9px}
@media(max-width:374px){
  .brand-copy em{display:none}
  .brand-copy b{font-size:15px}
  .brand-mark{width:27px;height:27px}
  .wallet{padding:0 6px;height:28px}
  .wallet b{font-size:11px}
  .wallet em{display:none}
  .hud{padding-left:10px;padding-right:10px;gap:6px}
  .hud-right{gap:4px}
}

/* panel system */
.panel-wrap{position:fixed;z-index:20;bottom:var(--tab-h);left:50%;transform:translateX(-50%);width:100%;max-width:var(--app-w);padding:0 8px;pointer-events:none}
.panel{
  display:none;pointer-events:auto;position:relative;
  max-height:41dvh;min-height:132px;
  border-radius:var(--radius) var(--radius) 0 0;
  background:linear-gradient(178deg,rgba(22,28,42,.9),rgba(9,12,20,.94) 58%,rgba(6,8,14,.97));
  border:1px solid rgba(255,255,255,.11);border-bottom:0;
  box-shadow:0 -18px 60px rgba(0,0,0,.55),inset 0 1px 0 rgba(255,255,255,.15);
  backdrop-filter:blur(22px) saturate(145%);
  -webkit-backdrop-filter:blur(22px) saturate(145%);
  overflow:hidden;
}
.panel::before{content:"";position:absolute;left:10%;right:10%;top:0;height:1px;background:linear-gradient(90deg,transparent,rgba(255,255,255,.6),transparent);pointer-events:none}
.panel::after{content:"";position:absolute;inset:0;pointer-events:none;border-radius:inherit;background:radial-gradient(100% 40% at 50% 0%,rgba(79,227,255,.055),transparent 70%)}
.panel.active{display:flex;flex-direction:column;animation:panelIn .34s cubic-bezier(.2,.8,.2,1)}

.pack-strip{padding-bottom:8px}
.pack-card{width:104px;padding:0;border-radius:13px;overflow:hidden;background:#0b0f18;border:1px solid rgba(255,255,255,.1);text-align:left;position:relative;transition:transform .18s,border-color .18s,box-shadow .18s;flex:0 0 auto}
.pack-card:active{transform:scale(.96)}
.pack-card .pk-art{position:relative;height:70px;overflow:hidden;background:linear-gradient(140deg,var(--pk-a,#222),var(--pk-b,#080b12))}
.pack-card .pk-art::before{content:"";position:absolute;inset:0;background:
  linear-gradient(115deg,transparent 10%,rgba(255,255,255,.16) 42%,transparent 60%),
  radial-gradient(80% 110% at 80% 0%,rgba(255,255,255,.2),transparent 55%)}
.pack-card .pk-art::after{content:"";position:absolute;left:-20%;right:-20%;top:46%;height:1px;background:rgba(255,255,255,.2);transform:rotate(-14deg)}
.pack-card .pk-code{position:absolute;left:7px;top:7px;font-size:7px;font-weight:900;letter-spacing:.12em;color:rgba(255,255,255,.65);z-index:1}
.pack-card .pk-glyph{position:absolute;right:6px;bottom:2px;font-size:30px;font-weight:900;font-style:italic;letter-spacing:-.08em;color:rgba(255,255,255,.12);line-height:1;z-index:1;text-transform:uppercase}
.pack-card .pk-body{padding:6px 7px 7px;position:relative;z-index:1}
.pack-card .pk-name{font-size:8.5px;font-weight:900;letter-spacing:.02em;line-height:1.15;min-height:20px;text-transform:uppercase;color:#eef3ff}
.pack-card .pk-foot{display:flex;align-items:center;justify-content:space-between;margin-top:4px}
.pack-card .pk-cost{font-size:8.5px;font-weight:900;color:#ffe7a8;font-variant-numeric:tabular-nums}
.pack-card .pk-odds{display:flex;gap:2px}
.pack-card .pk-odds i{width:3px;height:7px;border-radius:1px;display:block}
.pack-card.selected{border-color:var(--pk-sel,#ff3d86);box-shadow:0 0 0 1px var(--pk-sel,#ff3d86),0 8px 22px rgba(0,0,0,.45),0 0 24px var(--pk-glow,rgba(255,61,134,.25));transform:translateY(-1px)}
.pack-card.selected::after{content:"";position:absolute;inset:0;border-radius:inherit;pointer-events:none;border:1px solid rgba(255,255,255,.26)}
.pack-card.selected .pk-name{color:#fff}
.odds-line{display:flex;align-items:center;justify-content:space-between;gap:4px;margin-top:1px}
.odds-line .odds-title{font-size:8px;letter-spacing:.16em;color:var(--dim);font-weight:800;text-transform:uppercase;white-space:nowrap}
.odds-chips{display:flex;gap:3px;flex:1;justify-content:flex-end;flex-wrap:wrap}
.odds-chip{display:flex;align-items:center;gap:3px;font-size:7px;font-weight:800;color:var(--muted);letter-spacing:.02em;white-space:nowrap;padding:2px 4px;border-radius:4px;background:rgba(255,255,255,.04)}
.odds-chip b{color:#e8eefc;font-size:7.5px;font-weight:900}
.rip-actions{display:flex;gap:8px;align-items:stretch;margin-top:8px}
.rip-actions .btn-primary{flex:1}
.rip-actions .auto-box{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;min-width:74px;padding:0 8px;border-radius:13px;background:rgba(255,255,255,.035);border:1px solid var(--line)}
.rip-actions .auto-box .toggle{font-size:7.5px;letter-spacing:.1em}
.auto-state{font-size:7px;letter-spacing:.1em;color:var(--dim);text-transform:uppercase}
.rip-meta{display:flex;align-items:center;justify-content:space-between;margin-top:5px;font-size:7.5px;color:var(--dim);letter-spacing:.08em}
.rip-meta b{color:#d8e2f5;font-weight:800}
.pity-note{display:flex;align-items:center;gap:4px}
.reveal-tag{
  position:fixed;z-index:28;left:50%;top:calc(56px + env(safe-area-inset-top,0px) + 10px);
  transform:translateX(-50%);display:flex;align-items:center;gap:8px;
  padding:7px 14px 7px 8px;border-radius:999px;
  background:rgba(8,11,19,.82);border:1px solid var(--line-2);
  backdrop-filter:blur(14px);box-shadow:0 12px 34px rgba(0,0,0,.5);
  animation:tagIn .35s cubic-bezier(.2,.8,.2,1);pointer-events:none;max-width:calc(100% - 30px)
}
.reveal-tag[hidden]{display:none}
.reveal-tag .rt-badge{display:grid;place-items:center;width:38px;height:38px;border-radius:10px;font-size:8px;font-weight:900;letter-spacing:.04em;text-align:center;line-height:1.05;border:1px solid;background:rgba(0,0,0,.35)}
.reveal-tag .rt-copy{display:flex;flex-direction:column;gap:2px;min-width:0}
.reveal-tag .rt-copy b{font-size:12px;font-weight:900;letter-spacing:.04em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:190px}
.reveal-tag .rt-copy span{font-size:8px;letter-spacing:.1em;color:var(--muted);text-transform:uppercase;white-space:nowrap}
.reveal-tag .rt-new{font-size:9px;font-weight:900;letter-spacing:.08em;color:#041310;background:var(--green);padding:3px 7px;border-radius:5px}
.reveal-tag .rt-dup{font-size:9px;font-weight:900;letter-spacing:.08em;color:#0a1520;background:var(--cyan);padding:3px 7px;border-radius:5px}
@keyframes tagIn{from{opacity:0;transform:translate(-50%,-8px) scale(.94)}to{opacity:1;transform:translate(-50%,0) scale(1)}}

/* GARAGE */
.filter-row{display:flex;gap:5px;overflow-x:auto;scrollbar-width:none;padding:1px 0 7px;touch-action:pan-x}
.filter-row::-webkit-scrollbar{display:none}
.filter-row .chip{flex:0 0 auto;height:25px;padding:0 9px;font-size:8px}
.roster{display:flex;gap:7px;overflow-x:auto;scrollbar-width:none;padding:1px 1px 8px;touch-action:pan-x;scroll-snap-type:x proximity}
.roster::-webkit-scrollbar{display:none}
.car-card{width:116px;flex:0 0 auto;border-radius:12px;background:linear-gradient(155deg,rgba(255,255,255,.075),rgba(255,255,255,.022));border:1px solid var(--line);overflow:hidden;text-align:left;position:relative;scroll-snap-align:start;transition:transform .16s,border-color .16s}
.car-card:active{transform:scale(.96)}
.car-card.locked{opacity:.62}
.car-card.selected{border-color:var(--rar,#fff);box-shadow:0 0 0 1px var(--rar,#fff),0 6px 18px rgba(0,0,0,.4)}
.car-card .cc-top{height:54px;position:relative;background:linear-gradient(160deg,var(--rar-soft,rgba(255,255,255,.1)),rgba(4,6,12,.2) 70%);overflow:hidden;display:grid;place-items:center}
.car-card .cc-top::after{content:"";position:absolute;inset:0;background:linear-gradient(110deg,transparent 30%,rgba(255,255,255,.1) 47%,transparent 58%)}
.car-card .cc-car{width:86px;height:34px;filter:drop-shadow(0 4px 7px rgba(0,0,0,.6))}
.car-card .cc-rar{position:absolute;left:5px;top:5px;display:flex;align-items:center;gap:3px;font-size:6px;font-weight:900;letter-spacing:.08em;text-transform:uppercase;color:var(--rar,#fff);background:rgba(4,6,12,.55);padding:2px 4px;border-radius:3px;border:1px solid rgba(255,255,255,.1)}
.car-card .cc-trait{position:absolute;right:4px;top:4px;font-size:6px;padding:2px 4px;border-radius:3px;font-weight:900;letter-spacing:.05em}
.car-card .cc-body{padding:6px 7px 7px}
.car-card .cc-name{font-size:9px;font-weight:900;letter-spacing:.01em;line-height:1.1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;text-transform:uppercase}
.car-card .cc-stats{display:flex;gap:2px;margin-top:5px}
.car-card .cc-stat{flex:1;height:3px;border-radius:2px;background:rgba(255,255,255,.08);overflow:hidden}
.car-card .cc-stat i{display:block;height:100%;background:var(--rar,#fff);border-radius:2px}
.car-card .cc-foot{display:flex;align-items:center;justify-content:space-between;margin-top:5px;font-size:6.5px;color:var(--dim);letter-spacing:.04em}
.car-card .cc-foot b{color:#dfe8fa;font-weight:800}
.car-card .bp-chip{color:#9ff2ff}
.garage-note{display:flex;align-items:center;justify-content:space-between;margin:1px 0 7px;font-size:8px;color:var(--dim);letter-spacing:.06em}
.garage-note b{color:#dbe6fb}
.showcase-chips{display:flex;gap:3px}

/* WORKSHOP */
.ws-head{display:flex;align-items:center;gap:9px;margin:1px 0 8px}
.ws-thumb{width:46px;height:35px;border-radius:8px;background:linear-gradient(145deg,var(--rar-soft,rgba(255,255,255,.1)),rgba(0,0,0,.3));border:1px solid var(--line);display:grid;place-items:center;flex:0 0 auto}
.ws-thumb svg{width:40px;height:20px}
.ws-copy{min-width:0;flex:1}
.ws-copy b{display:block;font-size:12px;font-weight:900;letter-spacing:.02em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ws-copy span{display:flex;align-items:center;gap:4px;font-size:7.5px;color:var(--muted);letter-spacing:.06em;margin-top:2px}
.ws-level{text-align:right;font-size:7px;color:var(--dim);letter-spacing:.08em;line-height:1.4}
.ws-level b{display:block;font-size:14px;color:#e9f0ff;letter-spacing:0}
.upgrade-list{display:flex;flex-direction:column;gap:6px}
.upgrade-row{display:flex;align-items:center;gap:8px;padding:6px 7px 6px 9px;border-radius:11px;background:rgba(255,255,255,.035);border:1px solid var(--line)}
.upgrade-row.maxed{background:rgba(255,194,71,.05);border-color:rgba(255,194,71,.18)}
.up-label{width:52px;flex:0 0 auto}
.up-label b{display:block;font-size:8.5px;font-weight:900;letter-spacing:.12em;text-transform:uppercase}
.up-label span{display:block;font-size:7px;color:var(--dim);margin-top:1px;letter-spacing:.03em}
.up-mid{flex:1;min-width:0}
.up-meter{margin-bottom:3px}
.up-nums{display:flex;justify-content:space-between;font-size:6.5px;color:var(--dim);letter-spacing:.03em}
.up-nums b{color:#d9e2f3;font-weight:800}
.up-nums b.hot{color:var(--cyan)}
.up-btn{min-width:62px;min-height:36px;padding:0 7px;border-radius:8px;font-size:7px;line-height:1.15;display:flex;flex-direction:column;gap:1px;align-items:center;justify-content:center;letter-spacing:.05em;background:linear-gradient(145deg,rgba(255,255,255,.1),rgba(255,255,255,.03));border:1px solid var(--line-2)}
.up-btn b{font-size:9px;font-weight:900;color:#ffe6a3}
.up-btn span{font-size:6.5px;color:var(--muted);white-space:nowrap}
.up-btn:disabled{opacity:.4}
.up-btn:active{transform:scale(.95)}
.ws-links{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-top:8px}
.ws-link{display:flex;align-items:center;gap:7px;padding:7px 9px;border-radius:10px;background:rgba(255,255,255,.035);border:1px solid var(--line);text-align:left;min-height:42px}
.ws-link:active{transform:scale(.97)}
.ws-link .li{width:24px;height:24px;border-radius:7px;display:grid;place-items:center;background:rgba(79,227,255,.1);color:var(--cyan);font-size:12px;flex:0 0 auto}
.ws-link.vault .li{color:var(--gold);background:rgba(255,194,71,.1)}
.ws-link .lc{min-width:0}
.ws-link .lc b{display:block;font-size:8px;font-weight:900;letter-spacing:.11em}
.ws-link .lc span{display:block;font-size:6.5px;color:var(--dim);margin-top:1px;white-space:nowrap}
.ws-link .la{margin-left:auto;color:var(--dim);font-size:12px}

/* RACE */
.track-card{width:125px;flex:0 0 auto;border-radius:11px;overflow:hidden;background:#0a0e17;border:1px solid var(--line);text-align:left;transition:transform .16s,border-color .16s;position:relative}
.track-card:active{transform:scale(.96)}
.track-card .tk-art{height:46px;position:relative;background:linear-gradient(135deg,var(--t1,#222),var(--t2,#05070c));overflow:hidden}
.track-card .tk-art::after{content:"";position:absolute;inset:0;background:linear-gradient(100deg,transparent 35%,rgba(255,255,255,.13) 48%,transparent 58%)}
.track-card .tk-glyph{position:absolute;left:6px;bottom:-4px;font-size:27px;font-weight:900;font-style:italic;letter-spacing:-.08em;color:rgba(255,255,255,.17);line-height:1}
.track-card .tk-num{position:absolute;right:5px;top:4px;font-size:6px;letter-spacing:.12em;color:rgba(255,255,255,.55);font-weight:900}
.track-card .tk-body{padding:5px 7px 7px}
.track-card .tk-name{font-size:8px;font-weight:900;letter-spacing:.01em;line-height:1.15;min-height:20px;text-transform:uppercase}
.track-card .tk-meta{display:flex;align-items:center;justify-content:space-between;margin-top:3px;font-size:6.5px;color:var(--dim);letter-spacing:.03em}
.track-card .tk-meta b{color:#ffe0a0;font-weight:900;font-variant-numeric:tabular-nums}
.track-card.selected{border-color:var(--tacc,#ff3d86);box-shadow:0 0 0 1px var(--tacc,#ff3d86),0 0 18px rgba(255,61,134,.2)}
.track-card .tk-diff{display:flex;gap:2px}
.track-card .tk-diff i{width:4px;height:4px;border-radius:50%;background:rgba(255,255,255,.16)}
.track-card .tk-diff i.on{background:var(--tacc,#ff3d86);box-shadow:0 0 5px var(--tacc)}
.race-info{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:2px}
.race-info .race-loc{min-width:0}
.race-info .race-loc b{display:block;font-size:11px;font-weight:900;letter-spacing:.06em;text-transform:uppercase;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.race-info .race-loc span{font-size:7.5px;color:var(--muted);letter-spacing:.05em}
.race-launch{display:flex;gap:7px;align-items:center;margin-top:8px}
.race-launch .btn-primary{flex:1}
.race-best{text-align:right;min-width:58px}
.race-best span{display:block;font-size:6.5px;color:var(--dim);letter-spacing:.08em}
.race-best b{display:block;font-size:11px;color:#eaf1ff;font-variant-numeric:tabular-nums;letter-spacing:.02em}
.race-hud{position:fixed;z-index:24;left:50%;transform:translateX(-50%);width:100%;max-width:var(--app-w);top:calc(52px + env(safe-area-inset-top,0px));padding:0 14px;pointer-events:none}
.race-hud[hidden]{display:none}
.race-hud-top{display:flex;gap:6px}
.race-pill{flex:1;display:flex;align-items:baseline;justify-content:center;gap:4px;height:36px;border-radius:10px;background:rgba(7,10,17,.7);border:1px solid var(--line);backdrop-filter:blur(10px);box-shadow:inset 0 1px 0 rgba(255,255,255,.08)}
.race-pill span{font-size:6.5px;color:var(--dim);letter-spacing:.13em;font-weight:800}
.race-pill b{font-size:15px;font-weight:900;font-variant-numeric:tabular-nums;color:#f1f6ff;letter-spacing:.01em}
.race-pill em{font-size:6.5px;font-style:normal;color:var(--dim);letter-spacing:.04em}
.race-pill:nth-child(1) b{color:var(--gold)}
