const base = 'http://127.0.0.1:9222';
const sleep = ms => new Promise(r => setTimeout(r, ms));

async function waitFor(fn, ms = 15000) {
  const start = Date.now();
  let last;
  while (Date.now() - start < ms) {
    try { return await fn(); } catch (e) { last = e; await sleep(250); }
  }
  throw last;
}

const tabs = await waitFor(async () => {
  const r = await fetch(`${base}/json/new?http://127.0.0.1:8099/`, { method: 'PUT' });
  if (!r.ok) throw new Error('new tab failed ' + r.status);
  return [await r.json()];
});
const target = tabs[0];
const ws = new WebSocket(target.webSocketDebuggerUrl);
let id = 0;
const pending = new Map();
ws.onmessage = ev => {
  const msg = JSON.parse(ev.data);
  if (msg.id && pending.has(msg.id)) {
    const { resolve, reject } = pending.get(msg.id);
    pending.delete(msg.id);
    if (msg.error) reject(new Error(JSON.stringify(msg.error)));
    else resolve(msg.result);
  }
};
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
const send = (method, params = {}) => new Promise((resolve, reject) => {
  const mid = ++id;
  pending.set(mid, { resolve, reject });
  ws.send(JSON.stringify({ id: mid, method, params }));
});
const evalJs = async expression => {
  const r = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true });
  if (r.exceptionDetails) throw new Error('JS error: ' + JSON.stringify(r.exceptionDetails));
  return r.result.value;
};

await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 2, mobile: true });
await send('Runtime.enable');
await send('Page.enable');
await waitFor(async () => (await evalJs('!!(window.__apex && window.__apex.world)')) === true, 20000);

const errs = await evalJs(`(() => {
  const a = window.__apex;
  if (!a || !a.world) return { ok: false };
  let pack = a.world.rip.pack;
  if (!pack) {
    const first = document.querySelector('[data-pack]');
    if (first) first.click();
    pack = a.world.rip.pack;
  }
  if (!pack) return { ok: false, reason: 'no pack' };
  const body = pack.userData.body || pack;
  window.__spinProbe = { pack, body, start: body.rotation.y };
  return { ok: true, hasBody: !!(pack.userData.body), y: body.rotation.y, visible: pack.visible, tab: a.store.state.activeTab };
})()`);

await sleep(1400);
const probe1 = await evalJs(`(() => {
  const p = window.__spinProbe;
  const body = p.body;
  return { y: body.rotation.y, x: body.rotation.x, bob: p.pack.position.y, spin: body.rotation.y - p.start };
})()`);
await sleep(1200);
const probe2 = await evalJs(`(() => {
  const p = window.__spinProbe;
  const body = p.body;
  return { y: body.rotation.y, x: body.rotation.x, bob: p.pack.position.y, spin: body.rotation.y - p.start };
})()`);
const layout = await evalJs(`(() => ({
  w: innerWidth, h: innerHeight,
  docH: document.documentElement.scrollHeight,
  errs: (window.__apex && window.__apex.errors) || null,
}))()`);
console.log(JSON.stringify({ errs, probe1, probe2, layout }, null, 2));
ws.close();

